{"content": "// Task CRUD and status transitions.

import { findById, validateExists } from './users.js';
import { canDelete } from './permissions.js';
import { Cache } from './cache.js';
import { record } from './audit.js';

const VALID_TRANSITIONS = {
  open: 'in_progress',
  in_progress: 'done',
  done: null,
};

class TaskManager {
  tasks = new Map();
  cache;

  constructor(cache = new Cache()) {
    this.cache = cache;
  }

  create(input) {
    if (!input.title?.trim()) {
      throw new Error('Title must not be empty');
    }
    if (!['open', 'in_progress', 'done'].includes(input.status)) {
      throw new Error(`Invalid status: ${input.status}`);
    }

    validateExists(input.createdBy);
    validateExists(input.assignee);

    const task = {
      ...input,
      id: Math.random().toString(36).slice(2),
      createdAt: Date.now(),
    };

    this.tasks.set(task.id, task);
    this.cache.set(task.id, task, 60000);
    record({ action: 'create', userId: input.createdBy, taskId: task.id, timestamp: Date.now() });

    return task;
  }

  getTask(id) {
    const cached = this.cache.get(id);
    if (cached) return cached;
    const task = this.tasks.get(id) ?? null;
    if (task) {
      this.cache.set(id, task, 60000);
    }
    return task;
  }

  updateStatus(id, status) {
    const task = this.tasks.get(id);
    if (!task) return null;

    const allowed = VALID_TRANSITIONS[task.status];
    if (allowed !== status) {
      throw new Error(
        `Invalid status transition: ${task.status} -> ${status}`
      );
    }

    task.status = status;
    this.cache.invalidate(id);
    record({ action: 'status_change', userId: task.createdBy, taskId: id, timestamp: Date.now() });

    return task;
  }

  delete(id, userId) {
    const task = this.tasks.get(id);
    if (!task) return false;

    if (!canDelete(task, userId)) return false;

    this.tasks.delete(id);
    this.cache.invalidate(id);
    record({ action: 'delete', userId, taskId: id, timestamp: Date.now() });

    return true;
  }

  listByUser(userId) {
    return Array.from(this.tasks.values()).filter(
      (t) => t.assignee === userId || t.createdBy === userId
    );
  }

  listAll() {
    return Array.from(this.tasks.values());
  }

  clear() {
    this.tasks.clear();
    this.cache.clear();
  }
}

export const taskManager = new TaskManager();
", "path": "D:\桌面\step-cli-pi\benchmark\tasks\feature\feature-spec-001\repo\src\tasks.js"}

